WITH RECURSIVE CTE AS (
    SELECT EMPLOYEE_ID, NONEXISTENT_COL FROM TESTDB..EMPLOYEES
    UNION ALL
    SELECT EMPLOYEE_ID, NONEXISTENT_COL FROM CTE WHERE EMPLOYEE_ID < 100
)
SELECT * FROM CTE;

SELECT L1.LAST_NAME FROM (
    SELECT L2.EMPLOYEE_ID FROM (
        SELECT EMPLOYEE_ID FROM TESTDB..EMPLOYEES
    ) L2
) L1;

CREATE OR REPLACE PROCEDURE BAD_TYPE_PROC()
RETURNS INT4
LANGUAGE NZPLSQL AS
BEGIN_PROC
DECLARE
    v_bad INVALID_TYPE_XYZ;
BEGIN
    RETURN 1;
END;
END_PROC;

SELECT * FROM (
    SELECT * FROM (
        SELECT NONEXISTENT_COL FROM TESTDB..EMPLOYEES
    ) L2
) L1;

SELECT SUB.FAKE_COL
FROM (
    SELECT E.EMPLOYEE_ID FROM TESTDB..EMPLOYEES E
) SUB;

SELECT 
    ROW_NUMBER() OVER (PARTITION BY DEPARTMENT_ID ORDER BY FAKE_COLUMN) AS RN
FROM TESTDB..EMPLOYEES;

SELECT 
    ROW_NUMBER() OVER (PARTITION BY FAKE_COLUMN ORDER BY EMPLOYEE_ID) AS RN
FROM TESTDB..EMPLOYEES;

SELECT 
    CASE WHEN FAKE_COLUMN > 100 THEN 'High' ELSE 'Low' END
FROM TESTDB..EMPLOYEES;

WITH CTE_TEST AS (
    SELECT NONEXISTENT_COLUMN, FIRST_NAME 
    FROM TESTDB..EMPLOYEES
)
SELECT * FROM CTE_TEST;

SELECT OUTER_SUB.FAKE_COL FROM (
    SELECT E.EMPLOYEE_ID FROM TESTDB..EMPLOYEES E
) OUTER_SUB;

WITH CTE_EMP AS (
    SELECT EMPLOYEE_ID, FIRST_NAME FROM TESTDB..EMPLOYEES
)
SELECT CTE_EMP.FAKE_COLUMN FROM CTE_EMP;

SELECT OUTER_ALIAS.FAKE_COL FROM (
    SELECT E.EMPLOYEE_ID FROM TESTDB..EMPLOYEES E
) OUTER_ALIAS;

CREATE OR REPLACE PROCEDURE BAD_TYPE()
RETURNS INT4
LANGUAGE NZPLSQL AS
BEGIN_PROC
DECLARE
    v_bad FOOBAR_TYPE;
BEGIN
    RETURN 1;
END;
END_PROC;

CREATE OR REPLACE PROCEDURE BAD_FN_PROC()
RETURNS INT4
LANGUAGE NZPLSQL AS
BEGIN_PROC
DECLARE
    v_x INT4;
BEGIN
    v_x := NONEXISTENT_FUNC_99(1, 2);
    RETURN v_x;
END;
END_PROC;

WITH DEPT_KEYS (KEY_ID) AS (
    SELECT D.DEPARTMENT_ID FROM TESTDB..DEPARTMENTS D
)
SELECT DK.DEPARTMENT_ID FROM DEPT_KEYS DK;

WITH CTE_RENAMED (ID, NAME) AS (
    SELECT EMPLOYEE_ID, FIRST_NAME FROM TESTDB..EMPLOYEES
)
SELECT EMPLOYEE_ID FROM CTE_RENAMED;

CREATE EXTERNAL TABLE ext_bad_types
(
    col1 WRONG_TYPE_INTEGER,
    col2 WRONG_TYPE_VARCHAR(10)
)
USING (DATAOBJECT ('/tmp/data.csv') FORMAT TEXT);

CREATE OR REPLACE PROCEDURE TESTDB.PUBLIC.P_STR_CASE_BAD()
RETURNS INT4
LANGUAGE NZPLSQL AS
'BEGIN
    RETURN CASE WHEN 1 = 1 THEN 1;
END;';
